        const int fd = open(path, O_RDONLY);
        if (fd < 0) {
            return;
        }
        struct stat info{};
        if (fstat(fd, &info) == 0) {
            void* p = mmap(nullptr, info.st_size, PROT_READ, MAP_PRIVATE, fd, 0);
            if (p != MAP_FAILED) {
                addr_ = p;
                size_ = info.st_size;
            }
        }
        close(fd);
    }
    ~MappedFile() {
        if (addr_ != nullptr) {
            munmap(addr_, size_);
        }
    }
    MappedFile(const MappedFile&) = delete;
    MappedFile& operator=(const MappedFile&) = delete;

    const char* data() const { return static_cast<const char*>(addr_); }
    std::size_t size() const { return size_; }

private:
    void* addr_ = nullptr;
    std::size_t size_ = 0;
};

int main() {
    {
        // Saves the fills from the input to fills.bin. Leave it as it is.
        std::ofstream out("fills.bin", std::ios::binary);
        Fill f{};
        while (std::cin >> f.price_ticks >> f.qty) {
            out.write(reinterpret_cast<const char*>(&f), sizeof f);
        }
    }

    const MappedFile file("fills.bin");
    if (file.data() == nullptr) {
        std::cout << "cannot map fills.bin\n";
        return 0;
    }
    int64_t count = 0;
    int64_t shares = 0;
    int64_t notional = 0;
    for (std::size_t offset = 0; offset + sizeof(Fill) <= file.size(); offset += sizeof(Fill)) {
        Fill f;
        std::memcpy(&f, file.data() + offset, sizeof f);
        ++count;
        shares += f.qty;
        notional += f.price_ticks * f.qty;
    }
    std::cout << count << " fills, " << shares << " shares, vwap " << std::fixed << std::setprecision(2)
              << static_cast<double>(notional) / shares << '\n';
    return 0;
}
